args.sql:
WITH vendor_vri AS (
  SELECT vm."Vendor_Trace", 
    (CASE vm."vendSecRate" WHEN 'A' THEN 4 WHEN 'B' THEN 3 WHEN 'C' THEN 2 WHEN 'D' THEN 1 END) * (CASE WHEN vm."contrState" = 'Active' THEN 1 ELSE 0.5 END) as vri
  FROM "VendorManagement" vm
)
SELECT vri, COUNT(*) as cnt FROM vendor_vri GROUP BY vri ORDER BY vri;

